/*
A FÓRMULA DE FAULHABER NOS DÁ A SOMA DE UMA POTÊNCIA p DOS n-ÉSIMOS PRIMEIROS NÚMEROS INTEIROS.
ESTA É UMA IMPORTANTE APLICAÇÃO DOS NÚMEROS DE BERNOULLI, ÚTIL POR EXEMPLO NO CÁLCULO DE SOMATÓRIOS.
PARA MAIORES INFORMAÇÕES: https://en.wikipedia.org/wiki/Faulhaber%27s_formula

*/


//Cabeçalho
#include"bernoulli_numbers.h"
#include<stdio.h>

//Fórmula de Faulhaber
uint64_t faulhaber_formula(uint64_t n, uint64_t power){
//Variáveis locais
uint64_t result=0;
uint64_t k;
//Procedimentos
for(k=0; k<=power; ++k){
result+=(combination(power+1, k)*bernoulli_number_generator_positive_sign(k)*pow(n, power-k+1));
                       };
//Resultado
return result/(power+1);
                                            };

