javascript:(function() {
  function replaceTextInHtml(find, replace, element) {
    if (element === undefined) {
      element = document.body;
    }

    var regex = new RegExp(find, 'gi');
    var childNodes = element.childNodes;
    for (var i = 0; i < childNodes.length; i++) {
      var node = childNodes[i];

      if (node.nodeType === Node.TEXT_NODE) {
        node.textContent = node.textContent.replace(regex, replace);
      } else {
        replaceTextInHtml(find, replace, node);
      }
    }
  }

  var textToFind = prompt("Find:");
  var textToReplace = prompt("Replace with:");

  replaceTextInHtml(textToFind, textToReplace);
})();

const fs = require('fs');
const path = require('path');

module.exports = function getStorybookVersionFromPackageJson(
  packageJsonPath = path.join(process.cwd(), 'package.json'),
) {
  const data = fs.readFileSync(packageJsonPath, 'utf8');
  const packageJson = JSON.parse(data);

  const combinedDependencies = {
    ...packageJson.dependencies,
    ...packageJson.devDependencies,
  };

  const storybookPackage = [
    'storybook',
    '@storybook/react',
    '@storybook/angular',
    '@storybook/vue',
  ].find((pkg) => combinedDependencies[pkg]);

  if (storybookPackage) {
    const storybookVersion = combinedDependencies[storybookPackage];
    const majorVersion = parseInt(storybookVersion.match(/\d/)[0], 10);
    return majorVersion;
  } else {
    throw new Error('Storybook is not listed as a dependency in package.json');
  }
};

