	if (argc != 3) {
		error("cc1 cpuname features");
		exit(1);
	}
	cputype = atoi(argv[1]);
	cpufeat = atol(argv[2]);
	next_token();
	init_nodes();
	/* A function with no type info returning INT */
	deffunctype = make_function(CINT, functype);
#ifdef DEBUG
	if (argv[1]) {
		debug = fopen(argv[1], "w");
		if (debug == NULL) {
			perror(argv[1]);
			return 255;
		}
	}
#endif
	while (token != T_EOF)
		toplevel();
	/* No write out any uninitialized variables */
	write_bss();
	out_write();
	return errors;
}

